CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE NOT NULL,
  "password" varchar NOT NULL,
  "phone" varchar,
  "enabled" bool,
  "created_at" timestamp
);

CREATE TABLE "users_profiles" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "role" varchar,
  "nickname" varchar,
  "bio" text,
  "enabled" bool
);

CREATE TABLE "spaces" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "host_profile_id" integer NOT NULL,
  "category_id" integer NOT NULL,
  "description" varchar,
  "phone1" varchar,
  "phone2" varchar,
  "email" varchar,
  "close_start" time,
  "close_end" time,
  "is_closed_at_public_holidays" bool,
  "is_visible" bool,
  "deleted_at" timestamp
);

CREATE TABLE "subspaces" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "space_id" integer NOT NULL,
  "description" varchar,
  "min_hours" integer,
  "max_hours" integer,
  "is_visible" bool,
  "deleted_at" timestamp
);

CREATE TABLE "categories" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL
);

CREATE TABLE "reservations" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "subspace_id" integer NOT NULL,
  "renter_profile_id" integer NOT NULL,
  "start" timestamp NOT NULL,
  "end" timestamp NOT NULL,
  "status" varchar NOT NULL,
  "renter_name" varchar,
  "renter_phone" varchar,
  "renter_email" varchar,
  "custom_request" varchar,
  "created_at" timestamp NOT NULL,
  "status_updated_at" timestamp,
  "cancelled_at" timestamp,
  "cancelled_by" integer
);

CREATE TABLE "holiday_rule" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "space_id" integer NOT NULL,
  "frequency_type" varchar,
  "day_mask" smallint,
  "nth_occurrence" smallint
);

CREATE TABLE "holiday_override" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "space_id" integer NOT NULL,
  "starts_at" date,
  "ends_at" date,
  "is_closed" bool,
  "day_mask" smallint,
  "priority_weight" integer
);

CREATE TABLE "images" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_url" varchar NOT NULL
);

CREATE TABLE "spaces_images" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "space_id" integer,
  "image_id" integer,
  "order_seq" integer
);

CREATE TABLE "subspaces_images" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "subspace_id" integer,
  "image_id" integer,
  "order_seq" integer
);

