COMMENT ON COLUMN "spaces"."phone1" IS 'allows different contacts for different spaces.';

COMMENT ON COLUMN "spaces"."phone2" IS 'allows different contacts for different spaces.';

COMMENT ON COLUMN "spaces"."email" IS 'allows different contacts for different spaces.';

COMMENT ON COLUMN "spaces"."close_start" IS 'The time space closes';

COMMENT ON COLUMN "spaces"."close_end" IS 'The time space opens. If `close_start` and `close_end` equals, the space stays open 24 hours a day.';

COMMENT ON COLUMN "reservations"."renter_name" IS 'Don''t use `users` table because 1. prevent sharing the latest renter info. to hosts 2. allow renters to reserve a space under a different person';

COMMENT ON TABLE "holiday_rule" IS '## Scenario A: "Every even week on Thursdays"
Entity: holiday_rule
Mapping: frequency_type = BI_WEEKLY, day_mask = 16, nth_occurrence = 0.
Verification: The system safely evaluates this by checking if the target date is a Thursday, then checking if ISO_WEEK % 2 == 0.

## Scenario B: "Every month on the 15th"
Entity: holiday_rule
Mapping: frequency_type = MONTHLY_FIXED_DATE, day_mask = 0 (ignored), nth_occurrence = 15.
Verification: The system completely bypasses the bitwise day math and strictly checks if targetDate.getDayOfMonth() == 15.

## Scenario C: "Every last week of the month on Fridays"
Entity: holidayRule
Mapping: frequency_type = MONTHLY_CALENDAR_WEEK, day_mask = 32, nth_occurrence = -1.
Verification: Safely accommodates 4-week, 5-week, and 6-week months by finding the visual calendar week of the actual last day of the target month, and matching it against the current date''s calendar week.
  ';

COMMENT ON COLUMN "holiday_rule"."frequency_type" IS 'Defines the temporal math. One of `WEEKLY`, `BI_WEEKLY`, `MONTHLY_NTH_OCCURRENCE`, `MONTHLY_CALENDAR_WEEK`,`MONTHLY_FIXED_DATE`, `LAST_DAY_OF_MONTH`.';

COMMENT ON COLUMN "holiday_rule"."day_mask" IS 'The sum of the target days of the week (Sun=1, Mon=2, Tue=4... Sat=64). Defaults to 127 (all days) if not applicable(`MONTHLY_FIXED_DATE`, `LAST_DAY_OF_MONTH`).';

COMMENT ON COLUMN "holiday_rule"."nth_occurrence" IS 'The modifier for the frequency type. Ignored for `WEEKLY` and `LAST_DAY_OF_MONTH`. For `BI_WEEKLY` frequency type, `0`` means every even week of the month and `1` means every odd week of the month.';

COMMENT ON TABLE "holiday_override" IS '## Scenario : "Closed March 20–27, but only on Mon/Tue"
Entity: HolidayOverride
Mapping: start_date = 2026-03-20, end_date = 2026-03-27, is_closed = TRUE, day_mask = 6 (2 + 4).
Verification: When generating availability for March 2026, the engine evaluates this Priority 1 override. It sees a date falls within the range, but only triggers the is_closed status if the date''s bitwise day matches 6.
';

COMMENT ON COLUMN "holiday_override"."is_closed" IS 'TRUE to force a closure, FALSE to force an opening (e.g., opening on a normally closed holiday).';

COMMENT ON COLUMN "holiday_override"."day_mask" IS 'The sum of the target days of the week (Sun=1, Mon=2, Tue=4, ... Sat=64). Determines which days within the date range are affected. Defaults to 127.';

COMMENT ON COLUMN "holiday_override"."priority_weight" IS 'Used to resolve conflicts if multiple overrides overlap the exact same dates and duration. Higher numbers win.';

