ALTER TABLE "holiday_override" ADD FOREIGN KEY ("space_id") REFERENCES "spaces" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "spaces_images" ADD FOREIGN KEY ("space_id") REFERENCES "spaces" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "spaces_images" ADD FOREIGN KEY ("image_id") REFERENCES "images" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "subspaces_images" ADD FOREIGN KEY ("subspace_id") REFERENCES "subspaces" ("id") DEFERRABLE INITIALLY IMMEDIATE;

